:root {
  /* Celestial Observatory Theme - starfield gradients and glassy instruments */
  --bg-primary: #05070d;
  --bg-alt: #0d1324;
  --text-primary: #f5f8ff;
  --text-secondary: #b8c7ff;
  --accent: #7ad0ff;
  --accent-2: #ffd480;
  --border: rgba(122, 208, 255, 0.38);
  --parallax-x: 0px;
  --parallax-y: 0px;
}

body {
  background: radial-gradient(circle at 20% 25%, rgba(122, 208, 255, 0.18), transparent 30%),
              radial-gradient(circle at 78% 65%, rgba(255, 212, 128, 0.16), transparent 34%),
              linear-gradient(160deg, #05070d 0%, #0d1324 65%, #05070d 100%);
  color: var(--text-primary);
}

body::before {
  content: '';
  position: fixed;
  inset: 0;
  background-image: radial-gradient(1px 1px at 20% 30%, rgba(255, 255, 255, 0.8), transparent),
                    radial-gradient(1px 1px at 40% 70%, rgba(122, 208, 255, 0.9), transparent),
                    radial-gradient(1px 1px at 70% 40%, rgba(255, 212, 128, 0.8), transparent),
                    radial-gradient(1px 1px at 85% 20%, rgba(255, 255, 255, 0.7), transparent);
  background-size: 240px 240px, 260px 260px, 300px 300px, 340px 340px;
  opacity: 0.7;
  pointer-events: none;
  transform: translate(var(--parallax-x), var(--parallax-y));
  transition: transform 0.2s ease;
}

.card {
  background: linear-gradient(130deg, rgba(122, 208, 255, 0.14), rgba(13, 19, 36, 0.9)), rgba(10, 15, 28, 0.9);
  border: 1px solid var(--border);
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.45), 0 0 1px rgba(122, 208, 255, 0.35);
  position: relative;
  overflow: hidden;
  backdrop-filter: blur(10px) saturate(130%);
}

.card::before {
  content: '';
  position: absolute;
  inset: 10%;
  border: 1px solid rgba(122, 208, 255, 0.14);
  border-radius: 12px;
  pointer-events: none;
}

.card::after {
  content: '';
  position: absolute;
  inset: -20%;
  background: radial-gradient(circle at 30% 30%, rgba(122, 208, 255, 0.22), transparent 45%),
              radial-gradient(circle at 72% 60%, rgba(255, 212, 128, 0.18), transparent 42%);
  mix-blend-mode: screen;
  opacity: 0.7;
  filter: blur(30px);
  pointer-events: none;
}

.card-title {
  text-transform: uppercase;
  letter-spacing: 1.2px;
  background: linear-gradient(90deg, var(--accent), var(--accent-2));
  -webkit-background-clip: text;
  color: transparent;
}

.badge {
  background: rgba(255, 212, 128, 0.12);
  color: var(--text-primary);
  border: 1px solid rgba(255, 212, 128, 0.35);
}

.button {
  background: linear-gradient(120deg, rgba(122, 208, 255, 0.2), rgba(255, 212, 128, 0.16));
  border: 1px solid rgba(122, 208, 255, 0.5);
  color: var(--text-primary);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.button:hover {
  transform: translateY(-2px);
  box-shadow: 0 18px 28px rgba(122, 208, 255, 0.28);
}
